import{_ as i,o as a,c as r,ai as o}from"./chunks/framework.lvpqbiZd.js";const u=JSON.parse('{"title":"Asumi Hybrid 3D Hero Design","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-08-31-asumi-hybrid-3d-hero-design.md","filePath":"superpowers/specs/2026-08-31-asumi-hybrid-3d-hero-design.md"}'),t={name:"superpowers/specs/2026-08-31-asumi-hybrid-3d-hero-design.md"};function n(s,e,l,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="asumi-hybrid-3d-hero-design" tabindex="-1">Asumi Hybrid 3D Hero Design <a class="header-anchor" href="#asumi-hybrid-3d-hero-design" aria-label="Permalink to “Asumi Hybrid 3D Hero Design”">​</a></h1><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p>Upgrade the existing Asumi hero into a cinematic desktop experience that follows the approved nine-beat sunrise storyboard while preserving an accessible, fast fallback.</p><h2 id="approved-storyline" tabindex="-1">Approved Storyline <a class="header-anchor" href="#approved-storyline" aria-label="Permalink to “Approved Storyline”">​</a></h2><ol><li>Begin in near-total darkness with a single horizon point.</li><li>Expand the sunrise and its vertical reflection.</li><li>Draw restrained orbital rings behind the focal point.</li><li>Reveal the spaced ASUMI wordmark.</li><li>Reveal the Japanese mark <code>明日美</code>.</li><li>Reveal <code>A Beautiful Tomorrow</code> and <code>آینده ای روشن</code>.</li><li>Introduce luminous ribbons and a sparse field of gold particles.</li><li>Enable damped pointer response for the light, camera, and ribbons.</li><li>Let scrolling compress the lockup and hand the viewer to an <code>آنچه می سازیم</code> preview.</li></ol><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h2><ul><li>Keep all semantic text, navigation, controls, and GSAP choreography in React DOM.</li><li>Render only the decorative sun, reflection, rings, ribbons, and particles in a lazy-loaded React Three Fiber canvas.</li><li>Keep the current SVG <code>HorizonScene</code> as the fallback for reduced motion, coarse pointers, narrow viewports, unsupported WebGL, and loading/error states.</li><li>Select the renderer through a pure capability function so the policy is independently testable.</li><li>Use a small custom shader for the ribbons and additive materials for glow. Do not add a post-processing pipeline or real-time shadows.</li></ul><h2 id="performance-and-accessibility" tabindex="-1">Performance And Accessibility <a class="header-anchor" href="#performance-and-accessibility" aria-label="Permalink to “Performance And Accessibility”">​</a></h2><ul><li>Limit WebGL DPR to <code>1.5</code> and use <code>powerPreference: high-performance</code>.</li><li>Pause the canvas when the hero is outside the viewport or the document is hidden.</li><li>Avoid scroll hijacking. Scroll only changes presentation progress and never captures the user&#39;s wheel or touch input.</li><li>Disable continuous pointer motion and show a complete static composition when <code>prefers-reduced-motion: reduce</code> is active.</li><li>Keep the canvas <code>aria-hidden</code>; the complete brand message remains readable in DOM.</li><li>Ensure the CTA and theme control remain keyboard reachable with visible focus.</li></ul><h2 id="visual-direction" tabindex="-1">Visual Direction <a class="header-anchor" href="#visual-direction" aria-label="Permalink to “Visual Direction”">​</a></h2><ul><li>Preserve Asumi&#39;s near-black graphite field and copper-gold palette.</li><li>The sun is a layered emissive point and soft halo at the horizon, not a literal sphere.</li><li>Rings are thin, imperfectly offset orbital lines with slow restrained drift.</li><li>Ribbons rise mainly from the right and cross the horizon with translucent additive blending.</li><li>Particles remain sparse and are concentrated around the sunrise and ribbon wake.</li><li>Pointer movement is capped to a subtle camera drift; text remains stable and legible.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>This phase implements the hero and a compact next-section transition preview only. Product pages, portfolio cards, product links, purchasing, and customer dashboard flows remain separate work.</p>',13)])])}const m=i(t,[["render",n]]);export{u as __pageData,m as default};
